#include <iostream>
#include <cstdio>
#include <bitset>
using namespace std;

const int N = 300000010;
bitset<N> prime;

int main()
{
    int l, r;
    scanf("%d%d", &l, &r);

    prime.set();
    prime[0] = prime[1] = false;

    for (int i = 3; i * i <= r; i += 2) {
        if (prime[i]) {
            for (int j = i * i; j <= r; j += 2 * i) {
                prime[j] = false;
            }
        }
    }

    int count = 0;
    if (l <= 2 && r >= 2)
        count++;

    for (int i = 5; i <= r; i += 4) {
        if (i >= l && prime[i])
            count++;
    }

    printf("%d\n", count);
    return 0;
}

